#include <bits/stdc++.h>
using namespace std;

int main(){
    int L, C;
    if(scanf("%d %d", &L, &C)!=2) return 0;

    const int V = 676;
    vector<vector<int>> g(L, vector<int>(C));
    vector<long long> rowS(L), colS(C);

    for(int i=0;i<L;i++){
        for(int j=0;j<C;j++){
            char a,b;
            scanf(" %c%c", &a, &b);
            g[i][j] = (a-'a')*26 + (b-'a');
        }
        scanf("%lld", &rowS[i]);
    }
    for(int j=0;j<C;j++) scanf("%lld", &colS[j]);

    // multiplicities of unknown variables per row / column
    vector<array<int,V>> rc(L), cc(C);
    for(int i=0;i<L;i++) rc[i].fill(0);
    for(int j=0;j<C;j++) cc[j].fill(0);

    vector<int> rowCnt(L,0), colCnt(C,0);
    vector<long long> rowKnown(L,0), colKnown(C,0);

    for(int i=0;i<L;i++){
        for(int j=0;j<C;j++){
            int v = g[i][j];
            if(rc[i][v]==0) rowCnt[i]++;
            if(cc[j][v]==0) colCnt[j]++;
            rc[i][v]++;
            cc[j][v]++;
        }
    }

    // for each variable, list of (row, mult) and (col, mult) where it appears
    vector<vector<pair<int,int>>> varRows(V), varCols(V);
    for(int i=0;i<L;i++)
        for(int v=0;v<V;v++)
            if(rc[i][v]>0) varRows[v].push_back({i, rc[i][v]});
    for(int j=0;j<C;j++)
        for(int v=0;v<V;v++)
            if(cc[j][v]>0) varCols[v].push_back({j, cc[j][v]});

    vector<long long> val(V, 0);
    vector<char> known(V, 0);

    queue<int> q;
    for(int i=0;i<L;i++) if(rowCnt[i]==1) q.push(i);
    for(int j=0;j<C;j++) if(colCnt[j]==1) q.push(L+j);

    while(!q.empty()){
        int t = q.front(); q.pop();
        if(t < L){
            int i = t;
            if(rowCnt[i] != 1) continue;
            int v = -1;
            for(int k=0;k<V;k++) if(rc[i][k]>0){ v=k; break; }
            if(v<0) continue;
            int mult = rc[i][v];
            long long rhs = rowS[i] - rowKnown[i];
            long long x = rhs / mult;
            val[v] = x;
            known[v] = 1;
            // update rows
            for(auto &pr : varRows[v]){
                int r = pr.first;
                if(rc[r][v] > 0){
                    rowKnown[r] += x * (long long)pr.second;
                    rc[r][v] = 0;
                    rowCnt[r]--;
                    if(rowCnt[r]==1) q.push(r);
                }
            }
            // update columns
            for(auto &pc : varCols[v]){
                int cIdx = pc.first;
                if(cc[cIdx][v] > 0){
                    colKnown[cIdx] += x * (long long)pc.second;
                    cc[cIdx][v] = 0;
                    colCnt[cIdx]--;
                    if(colCnt[cIdx]==1) q.push(L+cIdx);
                }
            }
        } else {
            int j = t - L;
            if(colCnt[j] != 1) continue;
            int v = -1;
            for(int k=0;k<V;k++) if(cc[j][k]>0){ v=k; break; }
            if(v<0) continue;
            int mult = cc[j][v];
            long long rhs = colS[j] - colKnown[j];
            long long x = rhs / mult;
            val[v] = x;
            known[v] = 1;
            for(auto &pr : varRows[v]){
                int r = pr.first;
                if(rc[r][v] > 0){
                    rowKnown[r] += x * (long long)pr.second;
                    rc[r][v] = 0;
                    rowCnt[r]--;
                    if(rowCnt[r]==1) q.push(r);
                }
            }
            for(auto &pc : varCols[v]){
                int cIdx = pc.first;
                if(cc[cIdx][v] > 0){
                    colKnown[cIdx] += x * (long long)pc.second;
                    cc[cIdx][v] = 0;
                    colCnt[cIdx]--;
                    if(colCnt[cIdx]==1) q.push(L+cIdx);
                }
            }
        }
    }

    // output in alphabetical order (aa..zz corresponds to index 0..675)
    string out;
    out.reserve(V*16);
    char name[3]; name[2]=0;
    for(int v=0;v<V;v++){
        if(known[v]){
            name[0] = char('a' + v/26);
            name[1] = char('a' + v%26);
            out += name;
            out += ' ';
            out += to_string(val[v]);
            out += '\n';
        }
    }
    fputs(out.c_str(), stdout);
    return 0;
}
